"""lab：給學生程式用的 API（在板子上執行）。

    import lab
    lab.sleep(0.5)            # 可被「停止」中斷的 sleep（請用這個，不要用 time.sleep）
    while lab.running(): ...  # 停止鍵按下後變 False
    lab.display.text("Hi", 0, 0); lab.display.show()   # T-QT Pro 螢幕（DevKit 上只記錄文字）
    lab.send(temp=25.3)       # 把數值送到 App 的主控台／感測值列
    lab.on_cmd(fn)            # 收 App 遙控頁的指令：fn({"op":"joy","x":..,"y":..})
    lab.led(1)                # 板載 LED（DevKit GPIO2；T-QT Pro 無 LED 時改亮螢幕角落）
"""
import time as _time

__version__ = "0.3.0"


class StopRequested(Exception):
    """停止鍵按下後，lab.sleep() 會丟出這個例外來結束程式。"""
    pass


_stop = False
_cmd_handler = None
_out_queue = []          # 由 runner／server 消費
display = None           # 由 lab.agent 依板子型號設定
board = "generic"
_pins = {}


def running():
    return not _stop


def sleep(seconds):
    """像 time.sleep，但每 50 ms 檢查停止旗標。"""
    end = _time.ticks_add(_time.ticks_ms(), int(seconds * 1000))
    while _time.ticks_diff(end, _time.ticks_ms()) > 0:
        if _stop:
            raise StopRequested()
        _time.sleep_ms(min(50, max(1, _time.ticks_diff(end, _time.ticks_ms()))))
    if _stop:
        raise StopRequested()


def emit(t, **kw):
    """內部用：排一則訊息給所有連線中的 App。"""
    kw["t"] = t
    _out_queue.append(kw)
    if len(_out_queue) > 200:
        del _out_queue[:50]


def log(*args):
    s = " ".join(str(a) for a in args)
    print(s)
    emit("out", s=s + "\n")


def send(**values):
    """把感測值送到 App：lab.send(temp=25.3, light=512)"""
    emit("sensor", v=values)


def on_cmd(fn):
    global _cmd_handler
    _cmd_handler = fn
    return fn


def _dispatch_cmd(cmd):
    if _cmd_handler:
        try:
            _cmd_handler(cmd)
        except Exception as e:
            emit("err", s="on_cmd 處理錯誤：%r\n" % e)


def pin(n, mode="out"):
    from machine import Pin
    key = (n, mode)
    if key not in _pins:
        _pins[key] = Pin(n, Pin.OUT if mode == "out" else Pin.IN)
    return _pins[key]


def led(v):
    from lab import boards
    p = boards.LED_PIN.get(board)
    if p is None:
        if display:
            display.fill_rect(120, 0, 8, 8, display.WHITE if v else display.BLACK)
            display.show()
        return
    pin(p).value(1 if v else 0)

