"""App 遙控頁的指令 → GPIO／PWM／ADC；其餘轉交 lab.on_cmd。"""
from machine import Pin, PWM, ADC
import lab

_pwm = {}
_adc = {}


def handle(cmd):
    op = cmd.get("op")
    try:
        if op == "pin":
            lab.pin(int(cmd["pin"])).value(1 if cmd.get("v") else 0)
        elif op == "pwm":
            p = int(cmd["pin"])
            if p not in _pwm:
                _pwm[p] = PWM(Pin(p), freq=int(cmd.get("freq", 1000)))
            elif "freq" in cmd:
                _pwm[p].freq(int(cmd["freq"]))
            duty = max(0, min(100, float(cmd.get("duty", 0))))
            _pwm[p].duty_u16(int(duty * 655.35))
        elif op == "adc":
            p = int(cmd["pin"])
            if p not in _adc:
                _adc[p] = ADC(Pin(p), atten=ADC.ATTN_11DB)
            lab.emit("sensor", v={"adc%d" % p: _adc[p].read_u16()})
        elif op == "read":
            p = int(cmd["pin"])
            lab.emit("sensor", v={"pin%d" % p: lab.pin(p, "in").value()})
        elif op == "led":
            lab.led(cmd.get("v"))
        else:
            lab._dispatch_cmd(cmd)
    except Exception as e:
        lab.emit("err", s="指令 %r 失敗：%r\n" % (cmd, e))

